// 临时验证脚本：复刻 mergeLingXiHouse 修复后的核心逻辑，验证三种场景
function makeStore(houses) {
  return {
    houseList: houses,
    setHouse(v) { this.houseList = v },
    project: '', houseId: '',
  }
}
function portal() { return { houseBoundViaAuth: false } }

function mergeLingXiHouse(lingXiData, userStore, portalStore) {
  if (!lingXiData || typeof lingXiData !== 'object') return
  const complexId = `${lingXiData.complexId || lingXiData.complexID || lingXiData.communityId || ''}`.trim()
  const houseId = `${lingXiData.houseId || lingXiData.houseID || lingXiData.roomId || ''}`.trim()
  if (!houseId) return
  const list = Array.isArray(userStore.houseList) ? [...userStore.houseList] : []
  const idx = list.findIndex((h) => !!h && `${h.houseId ?? ''}`.trim() === houseId)
  const existing = idx >= 0 ? list[idx] : null
  if (existing) {
    const lingXiName = `${lingXiData.complexName || lingXiData.communityName || lingXiData.name || ''}`.trim()
    const lingXiAddress = `${lingXiData.address || lingXiData.fullAddress || lingXiData.roomName || ''}`.trim()
    list.splice(idx, 1, {
      ...existing,
      complexId: complexId || existing.complexId || '',
      houseId,
      complexName: lingXiName && lingXiName !== '我的房屋' ? lingXiName : existing.complexName || lingXiName || '我的房屋',
      address: lingXiAddress && lingXiAddress !== '请选择房屋' ? lingXiAddress : existing.address || lingXiAddress || '请选择房屋',
    })
  }
  userStore.setHouse(list)
  if (complexId) userStore.project = complexId
  userStore.houseId = houseId
  portalStore.houseBoundViaAuth = true
}

function assert(cond, msg) { if (!cond) { console.error('FAIL:', msg); process.exitCode = 1 } else console.log('PASS:', msg) }

// 场景1（核心 bug）：接口已加载真实房屋，灵犀响应只有 houseId/complexId，无名称
{
  const s = makeStore([{ houseId: 'H1', complexId: 'C1', complexName: '春申花园', address: '春申路100号', extra: 'keep' }])
  const p = portal()
  mergeLingXiHouse({ houseId: 'H1', complexId: 'C1' }, s, p)
  assert(s.houseList[0].complexName === '春申花园', '场景1 真实小区名未被占位文案覆盖')
  assert(s.houseList[0].address === '春申路100号', '场景1 真实地址未被覆盖')
  assert(s.houseList[0].extra === 'keep', '场景1 已有行其它字段保留')
  assert(s.houseList.length === 1, '场景1 未重复插入房屋')
}

// 场景2：未命中（接口尚未落库），不应写入占位行
{
  const s = makeStore([{ houseId: 'H1', complexId: 'C1', complexName: '春申花园', address: '春申路100号' }])
  const p = portal()
  mergeLingXiHouse({ houseId: 'H2', complexId: 'C2' }, s, p)
  assert(s.houseList.length === 1, '场景2 未命中时不新增占位行')
  assert(s.houseList[0].complexName === '春申花园', '场景2 原真实列表保持不变')
  assert(p.houseBoundViaAuth === true && s.houseId === 'H2', '场景2 仍正确设置绑定标记与选中 houseId')
}

// 场景3：灵犀返回真实名称时取灵犀值
{
  const s = makeStore([{ houseId: 'H1', complexId: 'C1', complexName: '旧名', address: '旧址' }])
  mergeLingXiHouse({ houseId: 'H1', complexId: 'C1', complexName: '新小区', address: '新地址' }, s, portal())
  assert(s.houseList[0].complexName === '新小区' && s.houseList[0].address === '新地址', '场景3 灵犀真实名称/地址生效')
}

// 场景4：houseId 缺失直接返回，不污染列表
{
  const s = makeStore([{ houseId: 'H1', complexName: '春申花园' }])
  mergeLingXiHouse({ complexName: 'X' }, s, portal())
  assert(s.houseList.length === 1 && s.houseList[0].complexName === '春申花园', '场景4 houseId 缺失不改列表')
}

